{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Despite its significance, OH remains largely unintegrated into national governance and service delivery structures, with limited coordination across human health, animal health and environmental sectors [14], and only a few countries demonstrating uneven progress toward cross-sectoral integration [16].",
      "reason": "The Introduction thoroughly describes the current state of knowledge (existing studies, barriers, opportunities) and identifies the key uncertainty: limited clarity on how governance, financing, workforce and coordination influence OH integration into health systems."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "A comparative synthesis is therefore necessary to identify recurring structural barriers and enabling factors across diverse contexts. Accordingly, this systematic review synthesizes global evidence on the challenges and opportunities of integrating OH into national health systems...",
      "reason": "The need for the review is explicitly explained: existing literature is region-specific and conceptual, so a global comparative synthesis is required."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "More recent reviews published in 2025 [30-32] have examined operational challenges in rural African contexts, ethical considerations within a globalized OH framework and critical reflections from the Global South. Although these contributions broaden thematic and regional understanding, they primarily focus on conceptual or context-specific dimensions rather than systematically analysing how implementation barriers and facilitators intersect with core health system functions.",
      "reason": "Existing similar reviews are identified and cited, and the gap justifying the current review is articulated."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of implementation challenges and opportunities, not a review of intervention effects, so no mechanism of action is required."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review addresses health system integration of One Health rather than evaluating a complex intervention with defined components and outcomes; no logic model is required or reported."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "This review synthesizes global evidence on challenges, opportunities and strategic directions for embedding OH within health system structures.",
      "reason": "The abstract explicitly states the review objective. The review question is further structured using the PICo framework, as reported in text_7: 'Eligibility criteria were structured using the PICo framework (population, interest and context)'."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_7",
      "quote": "Eligibility criteria were structured using the PICo framework (population, interest and context), which is appropriate for non-clinical and policy-focused research questions",
      "reason": "This is a non-clinical, policy-focused review of implementation challenges and opportunities, not a review of intervention effects, so planned intervention comparisons (PICO) do not apply; the PICo variant was used instead."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Eligibility criteria were structured using the PICo framework (population, interest and context)... Population (P): national health systems, institutions and stakeholders involved in OH implementation. Interest (I): challenges, opportunities, barriers, facilitators and implementation strategies related to OH integration. Context (Co): human, animal and environmental health sectors at national or sub-national levels.",
      "reason": "Study characteristics for eligibility are specified via PICo framework covering population, interest, and context; no design restrictions noted ('no restrictions were placed on study design at the eligibility stage', text_10)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "This review includes peer-reviewed studies published between 1 June 2013, and 1 April 2025... Only peer-reviewed journal articles published in English were included. Conference abstracts lacking full-text availability were excluded... Grey literature was also excluded",
      "reason": "Report characteristics specified: publication date range, language (English), and publication status (peer-reviewed only; conference abstracts and grey literature excluded)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No distinction is made between excluding studies because outcomes were not measured versus outcomes not reported; no outcome-based exclusion criteria are described."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "Statements describing barriers, constraints or implementation difficulties were categorized as challenges; descriptions of enabling conditions or supportive factors were classified as opportunities; and proposed actions or policy suggestions were categorized as recommendations",
      "reason": "Synthesis groupings (challenges, opportunities, recommendations) are specified and align with review objectives, but explicit linkage to predefined comparisons in the objectives is not fully articulated."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "the start date was selected to align with the period in which OH gained formal global policy recognition and began to be operationalized through national and international frameworks",
      "reason": "Rationale for the date restriction is provided; additional rationales given for excluding conference abstracts and grey literature (text_7, text_34)."
    }
  ],
  "confidence": 88
}

